// app/app/coin-draw-centre.js — when the jackpot replay's centre becomes a craps battle.
//
// Draws award ordinary Craps seats through JackpotBattleEntry. The dice show only to a wallet drawn
// into the battle; the centre opens that wallet's awarded seat, including a losing run.

function normalAddress(value) {
  const address = String(value ?? '').trim().toLowerCase();
  return /^0x[0-9a-f]{40}$/.test(address) ? address : null;
}

/**
 * The centre's craps-battle model for `viewer` on a day whose roll-2 payload carried
 * `coinDrawBattle`, or null when the centre stays as it is. It says nothing about how the run
 * went or what the pot is: the battle shows both, and the pot is rolled there.
 */
export function coinDrawCentreModel(battle, viewer) {
  if (battle?.kind !== 'jackpot' || !Array.isArray(battle.entrants) || battle.entrants.length === 0) return null;
  const player = normalAddress(viewer);
  if (!player) return null;
  const index = battle.entrants.findIndex((row) => normalAddress(row?.player) === player);
  if (index < 0) return null;
  const seat = String(battle.entrants[index].betId ?? '');
  if (!/^[1-9]\d*$/.test(seat) || !/^0x[0-9a-f]{64}$/i.test(battle.key ?? '')) return null;
  return Object.freeze({
    key: battle.key,
    day: Number(battle.day),
    index,
    player,
    kind: 'jackpot',
    viewerBetId: seat,
    ariaLabel: 'You were drawn into the craps battle. Open it to watch your run.',
  });
}

/** Awarded jackpot seats cost the drawn player nothing: any credited FLIP is a gain. */
export function coinDrawResultTone(detail = {}) {
  if (detail.battleWonByViewer === true) return 'won';
  const paid = detail.viewerResult?.runPayoutWei;
  if (paid == null) return null;
  try { return BigInt(paid) > 0n ? 'profit' : 'lost'; }
  catch { return null; }
}
